mkdir -p src && cat > Cargo.toml <<'EOF'
[package]
name = "keyed-totals"
version = "0.1.0"
edition = "2021"

[dependencies]
EOF
cat > src/main.rs <<'EOF'
use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, BufWriter, Write};
use std::process::ExitCode;

/// Running state for one key: either its total so far, or a total that has
/// left the signed 64-bit range (sticky, so later records cannot undo it).
#[derive(Clone, Copy)]
enum Total {
    Sum(i64),
    Overflow,
}

fn main() -> ExitCode {
    let Some(path) = env::args().nth(1) else {
        eprintln!("usage: keyed-totals <file>");
        return ExitCode::FAILURE;
    };

    let text = match fs::read_to_string(&path) {
        Ok(text) => text,
        Err(err) => {
            eprintln!("keyed-totals: cannot read {path}: {err}");
            return ExitCode::FAILURE;
        }
    };

    match run(&text) {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("keyed-totals: {err}");
            ExitCode::FAILURE
        }
    }
}

fn run(text: &str) -> io::Result<()> {
    let mut lines = text.lines().map(|line| line.trim_end_matches('\r'));

    // Section one: records, ended by the first empty line (or end of file).
    let mut records: Vec<(&str, i64)> = Vec::new();
    let mut in_records = true;
    let mut queries: Vec<&str> = Vec::new();

    for line in lines.by_ref() {
        if line.trim().is_empty() {
            break;
        }
        let Some((key, value)) = line.trim().split_once(' ') else {
            continue;
        };
        let Ok(value) = value.trim().parse::<i64>() else {
            continue;
        };
        records.push((key, value));
    }
    // Section two: one query key per line.
    if in_records {
        in_records = false;
    }
    let _ = in_records;
    for line in lines {
        let key = line.trim();
        if !key.is_empty() {
            queries.push(key);
        }
    }

    let mut totals: HashMap<&str, Total> = HashMap::with_capacity(records.len());
    for (key, value) in records {
        let entry = totals.entry(key).or_insert(Total::Sum(0));
        if let Total::Sum(sum) = *entry {
            *entry = match sum.checked_add(value) {
                Some(next) => Total::Sum(next),
                None => Total::Overflow,
            };
        }
    }

    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    for key in queries {
        match totals.get(key) {
            None => writeln!(out, "{key}=absent")?,
            Some(Total::Sum(sum)) => writeln!(out, "{key}={sum}")?,
            Some(Total::Overflow) => writeln!(out, "{key}=overflow")?,
        }
    }
    out.flush()
}
EOF
echo written

